#!/usr/bin/env python3
"""Assemble hackage2ekapkgs' per-package output into hackage-packages.nix.

hackage2ekapkgs writes <dir>/<pkg>/default.nix (each `{ pkgs, lib,
callPackage }: self: { ... }`) plus an index <dir>/default.nix listing them
in order. This concatenates the attribute bodies, in index order, into one
attribute set with the same signature.

Usage: assemble-hackage-packages.py OUTPUT_DIR TARGET_FILE
"""

import re
import sys
from pathlib import Path

HEADER = """\
/* hackage-packages.nix is generated by scripts/regenerate-hackage-packages.sh
   (hackage2ekapkgs) -- DO NOT EDIT MANUALLY! */

{ pkgs, lib, callPackage }:

self: {
"""

FOOTER = "\n}\n"


def body(path: Path) -> str:
    text = path.read_text()
    start = text.index("self: {\n") + len("self: {\n")
    end = text.rindex("}")
    return text[start:end].strip("\n")


def main() -> None:
    out_dir, target = Path(sys.argv[1]), Path(sys.argv[2])
    index = (out_dir / "default.nix").read_text()
    names = re.findall(r"^\s*\(import \./(.+)\)$", index, flags=re.M)
    if not names:
        sys.exit(f"no packages listed in {out_dir / 'default.nix'}")

    bodies = [body(out_dir / name / "default.nix") for name in names]
    target.write_text(HEADER + "\n" + "\n\n".join(b for b in bodies if b) + "\n" + FOOTER)
    print(f"  {len(names)} packages -> {target}")


if __name__ == "__main__":
    main()
